-- Jhinuk AI Router — initial migration (0001_init).
-- Generated by hand to match prisma/schema.prisma (no live DB in the build VM).
-- Verify with: npx prisma migrate dev / npx prisma db push on a real Postgres.
-- NOTE: FallbackTrigger enum values are T429/T5XX in the DB (enum labels may
-- not start with a digit); the API maps them to "429"/"5XX".

CREATE TYPE "UserStatus" AS ENUM ('ACTIVE', 'SUSPENDED');
CREATE TYPE "ProviderType" AS ENUM ('openai','anthropic','gemini','deepseek','moonshot','glm','openrouter','tokens','ollama','custom');
CREATE TYPE "ProviderProtocol" AS ENUM ('openai','anthropic');
CREATE TYPE "RoutingMode" AS ENUM ('AUTOMATIC','MANUAL','HYBRID');
CREATE TYPE "UsageStatus" AS ENUM ('SUCCESS','FAILED');
CREATE TYPE "ProviderHealthStatus" AS ENUM ('UP','DEGRADED','DOWN');
CREATE TYPE "CreditTransactionType" AS ENUM ('PURCHASE','DEBIT','REFUND','ADJUSTMENT');
CREATE TYPE "FallbackTrigger" AS ENUM ('T429','T5XX','TIMEOUT','UNAVAILABLE');

CREATE TABLE "User" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "email" TEXT NOT NULL UNIQUE,
  "passwordHash" TEXT NOT NULL,
  "name" TEXT,
  "totpSecret" TEXT,
  "totpEnabled" BOOLEAN NOT NULL DEFAULT false,
  "status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE "Role" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "name" TEXT NOT NULL UNIQUE, "description" TEXT);
CREATE TABLE "Permission" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "name" TEXT NOT NULL UNIQUE);
CREATE TABLE "UserRole" (
  "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "roleId" UUID NOT NULL REFERENCES "Role"("id") ON DELETE CASCADE,
  PRIMARY KEY ("userId","roleId")
);
CREATE TABLE "RolePermission" (
  "roleId" UUID NOT NULL REFERENCES "Role"("id") ON DELETE CASCADE,
  "permissionId" UUID NOT NULL REFERENCES "Permission"("id") ON DELETE CASCADE,
  PRIMARY KEY ("roleId","permissionId")
);
CREATE TABLE "Team" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "name" TEXT NOT NULL,
  "ownerId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE
);
CREATE TABLE "TeamMember" (
  "teamId" UUID NOT NULL REFERENCES "Team"("id") ON DELETE CASCADE,
  "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "role" TEXT NOT NULL,
  PRIMARY KEY ("teamId","userId")
);
CREATE TABLE "UserSession" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "tokenHash" TEXT NOT NULL,
  "userAgent" TEXT,
  "ip" TEXT,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "revokedAt" TIMESTAMPTZ
);
CREATE INDEX "UserSession_userId_idx" ON "UserSession"("userId");
CREATE INDEX "UserSession_tokenHash_idx" ON "UserSession"("tokenHash");
CREATE TABLE "PasswordResetToken" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "tokenHash" TEXT NOT NULL UNIQUE,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "usedAt" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "PasswordResetToken_userId_idx" ON "PasswordResetToken"("userId");
CREATE TABLE "Provider" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "name" TEXT NOT NULL,
  "type" "ProviderType" NOT NULL,
  "baseUrl" TEXT NOT NULL,
  "protocol" "ProviderProtocol" NOT NULL,
  "enabled" BOOLEAN NOT NULL DEFAULT true,
  "isGlobal" BOOLEAN NOT NULL DEFAULT false,
  "ownerId" UUID REFERENCES "User"("id") ON DELETE CASCADE,
  "priority" INTEGER NOT NULL DEFAULT 0,
  "timeoutMs" INTEGER NOT NULL DEFAULT 30000,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE "ProviderCredential" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "providerId" UUID NOT NULL REFERENCES "Provider"("id") ON DELETE CASCADE,
  "userId" UUID REFERENCES "User"("id") ON DELETE CASCADE,
  "encryptedKey" TEXT NOT NULL,
  "keyHint" TEXT NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "rotatedAt" TIMESTAMPTZ
);
CREATE TABLE "AIModel" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "providerId" UUID NOT NULL REFERENCES "Provider"("id") ON DELETE CASCADE,
  "modelId" TEXT NOT NULL,
  "displayName" TEXT NOT NULL,
  "contextWindow" INTEGER NOT NULL,
  "maxOutputTokens" INTEGER NOT NULL,
  "supportsStreaming" BOOLEAN NOT NULL DEFAULT true,
  "supportsTools" BOOLEAN NOT NULL DEFAULT false,
  "supportsVision" BOOLEAN NOT NULL DEFAULT false,
  "supportsReasoning" BOOLEAN NOT NULL DEFAULT false,
  "enabled" BOOLEAN NOT NULL DEFAULT true,
  UNIQUE ("providerId","modelId")
);
CREATE TABLE "ModelPricing" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "modelId" UUID NOT NULL REFERENCES "AIModel"("id") ON DELETE CASCADE,
  "inputPricePer1M" DECIMAL(12,6) NOT NULL,
  "outputPricePer1M" DECIMAL(12,6) NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'USD',
  "effectiveFrom" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "effectiveTo" TIMESTAMPTZ
);
CREATE TABLE "ApiKey" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "name" TEXT NOT NULL,
  "keyHash" TEXT NOT NULL,
  "keyPrefix" VARCHAR(12) NOT NULL,
  "expiresAt" TIMESTAMPTZ,
  "lastUsedAt" TIMESTAMPTZ,
  "revokedAt" TIMESTAMPTZ,
  "restrictions" JSONB,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "ApiKey_userId_idx" ON "ApiKey"("userId");
CREATE INDEX "ApiKey_keyHash_idx" ON "ApiKey"("keyHash");
CREATE TABLE "RoutingProfile" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "name" TEXT NOT NULL,
  "mode" "RoutingMode" NOT NULL DEFAULT 'AUTOMATIC',
  "defaultProviderId" UUID,
  "defaultModelId" UUID,
  "taskMapping" JSONB NOT NULL,
  "preferredProviderId" UUID,
  "excludedModelIds" JSONB NOT NULL DEFAULT '[]',
  "fallbackModelIds" JSONB NOT NULL DEFAULT '[]',
  "budgetDailyCredits" DECIMAL(12,2),
  "isDefault" BOOLEAN NOT NULL DEFAULT false
);
CREATE INDEX "RoutingProfile_userId_idx" ON "RoutingProfile"("userId");
CREATE TABLE "RoutingRule" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "profileId" UUID NOT NULL REFERENCES "RoutingProfile"("id") ON DELETE CASCADE,
  "taskCategory" TEXT NOT NULL,
  "providerId" UUID,
  "modelId" UUID,
  "priority" INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE "FallbackRule" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID REFERENCES "User"("id") ON DELETE CASCADE,
  "profileId" UUID REFERENCES "RoutingProfile"("id") ON DELETE CASCADE,
  "fromModelId" UUID,
  "toModelId" UUID NOT NULL,
  "trigger" "FallbackTrigger" NOT NULL,
  "order" INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE "UsageRecord" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,
  "apiKeyId" UUID REFERENCES "ApiKey"("id") ON DELETE SET NULL,
  "requestId" TEXT NOT NULL UNIQUE,
  "provider" TEXT NOT NULL,
  "model" TEXT NOT NULL,
  "routingMode" "RoutingMode" NOT NULL,
  "taskCategory" TEXT,
  "inputTokens" INTEGER NOT NULL DEFAULT 0,
  "outputTokens" INTEGER NOT NULL DEFAULT 0,
  "cachedTokens" INTEGER NOT NULL DEFAULT 0,
  "tokensSaved" INTEGER NOT NULL DEFAULT 0,
  "estimatedCost" DECIMAL(12,6) NOT NULL DEFAULT 0,
  "platformCharge" DECIMAL(12,6) NOT NULL DEFAULT 0,
  "latencyMs" INTEGER NOT NULL DEFAULT 0,
  "status" "UsageStatus" NOT NULL DEFAULT 'SUCCESS',
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "UsageRecord_userId_createdAt_idx" ON "UsageRecord"("userId","createdAt");
CREATE INDEX "UsageRecord_provider_model_idx" ON "UsageRecord"("provider","model");
CREATE TABLE "CreditWallet" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,
  "balance" DECIMAL(12,2) NOT NULL DEFAULT 0,
  "currency" TEXT NOT NULL DEFAULT 'BDT'
);
CREATE TABLE "CreditTransaction" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "walletId" UUID NOT NULL REFERENCES "CreditWallet"("id") ON DELETE CASCADE,
  "amount" DECIMAL(12,2) NOT NULL,
  "type" "CreditTransactionType" NOT NULL,
  "idempotencyKey" TEXT NOT NULL UNIQUE,
  "requestId" TEXT,
  "description" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "CreditTransaction_walletId_createdAt_idx" ON "CreditTransaction"("walletId","createdAt");
CREATE TABLE "AuditLog" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "userId" UUID REFERENCES "User"("id") ON DELETE SET NULL,
  "action" TEXT NOT NULL,
  "resource" TEXT NOT NULL,
  "resourceId" TEXT,
  "meta" JSONB,
  "ip" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId","createdAt");
CREATE INDEX "AuditLog_resource_createdAt_idx" ON "AuditLog"("resource","createdAt");
CREATE TABLE "ProviderHealth" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "providerId" UUID NOT NULL UNIQUE REFERENCES "Provider"("id") ON DELETE CASCADE,
  "status" "ProviderHealthStatus" NOT NULL DEFAULT 'UP',
  "lastLatencyMs" INTEGER,
  "lastErrorRate" DOUBLE PRECISION,
  "lastCheckedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "consecutiveFailures" INTEGER NOT NULL DEFAULT 0,
  "cooldownUntil" TIMESTAMPTZ
);
CREATE TABLE "SystemSetting" (
  "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "key" TEXT NOT NULL UNIQUE,
  "value" JSONB NOT NULL,
  "updatedBy" TEXT
);

-- Seed roles + permissions (idempotent).
INSERT INTO "Role" ("name","description") VALUES
  ('SUPER_ADMIN','Full control'),('ADMIN','Admin'),('MANAGER','Manage users and providers'),
  ('USER','Standard user'),('VIEWER','Read-only')
ON CONFLICT ("name") DO NOTHING;

INSERT INTO "Permission" ("name") VALUES
  ('providers:create'),('providers:read'),('providers:update'),('providers:delete'),
  ('models:read'),('models:update'),
  ('users:read'),('users:create'),('users:update'),('users:suspend'),
  ('credits:adjust'),('settings:read'),('settings:update'),('audit:read'),
  ('api-keys:create'),('api-keys:read'),('api-keys:revoke'),
  ('routing:read'),('routing:update'),('usage:read'),('billing:read')
ON CONFLICT ("name") DO NOTHING;
